import { CommonModule } from '@angular/common';
import { Component } from '@angular/core';
import { FormArray, FormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { VotoService } from '../../services/voto.service';
import { VotoPayload } from '../../shared/models';

@Component({
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './voto.page.html'
})
export class VotoPageComponent {
  loading = false;
  saving = false;
  result: any = null;
  message = '';
  error = '';

  lookupForm = this.fb.nonNullable.group({
    votacaoId: [0, [Validators.required, Validators.min(1)]]
  });

  form = this.fb.group({
    usuarioId: [1, [Validators.required, Validators.min(1)]],
    conselhoId: [null as number | null],
    itens: this.fb.array([])
  });

  constructor(private fb: FormBuilder, private service: VotoService) {
    this.addItem();
  }

  get itens(): FormArray {
    return this.form.get('itens') as FormArray;
  }

  itemCriterios(index: number): FormArray {
    return this.itens.at(index).get('criterios') as FormArray;
  }

  addItem() {
    const item = this.fb.group({
      votacaoCandidatoId: [0, [Validators.required, Validators.min(1)]],
      escolhido: [false],
      nota: [null as number | null],
      criterios: this.fb.array([] as any[])
    });
    this.itens.push(item);
  }

  removeItem(index: number) {
    this.itens.removeAt(index);
  }

  addCriterio(itemIndex: number) {
    const criterios = this.itemCriterios(itemIndex);
    criterios.push(this.fb.group({
      criterioId: [0, [Validators.required, Validators.min(1)]],
      nota: [0, [Validators.required]]
    }));
  }

  removeCriterio(itemIndex: number, criterioIndex: number) {
    this.itemCriterios(itemIndex).removeAt(criterioIndex);
  }

  carregarVisualizacao() {
    if (this.lookupForm.invalid) return;
    this.loading = true;
    this.message = '';
    this.error = '';
    const id = Number(this.lookupForm.value.votacaoId);
    this.service.visualizar(id).subscribe({
      next: (res) => { this.result = res; this.loading = false; },
      error: () => { this.loading = false; this.error = 'Erro ao carregar visualização da votação.'; }
    });
  }

  submit() {
    if (this.form.invalid) return;
    this.saving = true;
    this.message = '';
    this.error = '';
    const votacaoId = Number(this.lookupForm.value.votacaoId || 0);
    const payload = this.form.getRawValue() as VotoPayload;
    this.service.votar(votacaoId, payload).subscribe({
      next: (res) => {
        this.saving = false;
        this.message = 'Voto enviado com sucesso.';
        this.result = res;
      },
      error: () => { this.saving = false; this.error = 'Erro ao enviar voto.'; }
    });
  }
}
