import { CommonModule } from '@angular/common';
import { Component, OnInit } from '@angular/core';
import { FormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { AnosService } from '../../services/anos.service';
import { Ano } from '../../shared/models';

@Component({
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './anos.page.html'
})
export class AnosPageComponent implements OnInit {
  items: Ano[] = [];
  loading = false;
  saving = false;
  message = '';
  error = '';

  form = this.fb.nonNullable.group({
    descricao: ['', [Validators.required, Validators.minLength(2)]]
  });

  constructor(private fb: FormBuilder, private service: AnosService) {}

  ngOnInit(): void { this.load(); }

  load() {
    this.loading = true;
    this.service.list().subscribe({
      next: (res) => { this.items = res ?? []; this.loading = false; },
      error: () => { this.loading = false; this.error = 'Falha ao carregar anos.'; }
    });
  }

  submit() {
    if (this.form.invalid) return;
    this.saving = true;
    this.service.create(this.form.getRawValue()).subscribe({
      next: () => {
        this.saving = false;
        this.message = 'Ano cadastrado.';
        this.form.reset({ descricao: '' });
        this.load();
      },
      error: () => { this.saving = false; this.error = 'Erro ao cadastrar ano.'; }
    });
  }
}
