import { Injectable } from '@angular/core';
import { jwtDecode } from 'jwt-decode';

@Injectable({
  providedIn: 'root'
})
export class AuthService {

  isAuthenticated(): boolean {

    const token = this.getToken();

    if (!token) {
      return false;
    }

    try {

      const decoded: any =
        jwtDecode(token);

      const now =
        Math.floor(Date.now() / 1000);

      if (decoded.exp < now) {

        this.logout();

        return false;
      }

      return true;

    } catch {

      this.logout();

      return false;
    }
  }

  getToken(): string | null {

    const token =
      localStorage.getItem('auth_token');

    if (!token) {
      return null;
    }

    try {

      const decoded: any =
        jwtDecode(token);

      const now =
        Math.floor(Date.now() / 1000);

      if (decoded.exp < now) {

        this.logout();

        return null;
      }

      return token;

    } catch {

      this.logout();

      return null;
    }
  }

  logout(): void {

    localStorage.removeItem('auth_token');
    localStorage.removeItem('usuario');
  }
}