import { Injectable } from '@angular/core';
import { ApiBaseService } from '../core/api-base.service';
import { Categoria } from '../shared/models';

@Injectable({ providedIn: 'root' })
export class CategoriasService extends ApiBaseService {
  list() { return this.http.get<Categoria[]>(`${this.baseUrl}/categorias`); }
  get(id: number) { return this.http.get<Categoria>(`${this.baseUrl}/categorias/${id}`); }
  create(payload: Categoria) { return this.http.post<Categoria>(`${this.baseUrl}/categorias`, payload); }
  update(id: number, payload: Categoria) { return this.http.put<Categoria>(`${this.baseUrl}/categorias/${id}`, payload); }
  delete(id: number) { return this.http.delete<void>(`${this.baseUrl}/categorias/${id}`); }
}
