import { Injectable } from '@angular/core';
import { HttpParams } from '@angular/common/http';
import { ApiBaseService } from '../core/api-base.service';
import { Apuracao } from '../shared/models';

@Injectable({ providedIn: 'root' })
export class ApuracoesService extends ApiBaseService {
  list(votacaoId?: number) {
    let params = new HttpParams();

    if (votacaoId !== undefined && votacaoId !== null) {
      params = params.set('votacaoId', votacaoId.toString());
    }

    return this.http.get<Apuracao[]>(`${this.baseUrl}/apuracoes`, { params });
  }
}
