import { Injectable } from '@angular/core';
import { ApiBaseService } from '../core/api-base.service';
import { Votacao, VotacaoCandidato } from '../shared/models';

@Injectable({ providedIn: 'root' })
export class VotacoesService extends ApiBaseService {
  list() { return this.http.get<Votacao[]>(`${this.baseUrl}/votacoes`); }
  get(id: number) { return this.http.get<Votacao>(`${this.baseUrl}/votacoes/${id}`); }
  create(payload: Votacao) { return this.http.post<Votacao>(`${this.baseUrl}/votacoes`, payload); }
  update(id: number, payload: Votacao) { return this.http.put<Votacao>(`${this.baseUrl}/votacoes/${id}`, payload); }
  delete(id: number) { return this.http.delete<void>(`${this.baseUrl}/votacoes/${id}`); }
}

@Injectable({ providedIn: 'root' })
export class VotacoesCandidatosService extends ApiBaseService {
  list() { return this.http.get<VotacaoCandidato[]>(`${this.baseUrl}/votacoes-candidatos`); }
  get(id: number) { return this.http.get<VotacaoCandidato>(`${this.baseUrl}/votacoes-candidatos/${id}`); }
  create(payload: VotacaoCandidato) { return this.http.post<VotacaoCandidato>(`${this.baseUrl}/votacoes-candidatos`, payload); }
  delete(id: number) { return this.http.delete<void>(`${this.baseUrl}/votacoes-candidatos/${id}`); }
}
