import { CommonModule } from '@angular/common';
import { Component, OnInit } from '@angular/core';
import { FormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { AnosService } from '../../services/anos.service';
import { CategoriasService } from '../../services/categorias.service';
import { VotacoesService } from '../../services/votacoes.service';
import { Ano, Categoria, Votacao } from '../../shared/models';
import { toDatetimeLocalValue } from '../../shared/form-utils';

@Component({
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './votacoes.page.html'
})
export class VotacoesPageComponent implements OnInit {
  items: Votacao[] = [];
  anos: Ano[] = [];
  categorias: Categoria[] = [];
  loading = false;
  saving = false;
  editingId: number | null = null;
  message = '';
  error = '';

  form = this.fb.nonNullable.group({
    anoId: ['2026', [Validators.required]],
    categoriaId: [0, [Validators.required, Validators.min(1)]],
    nome: ['', [Validators.required]],
    imagemUrl: ['', [Validators.required]],
    dataInicio: ['', [Validators.required]],
    dataFim: ['', [Validators.required]],
    dataPublicacao: ['', [Validators.required]],
    tipo: ['ESCOLHA_UNICA', [Validators.required]]
  });

  constructor(
    private fb: FormBuilder,
    private service: VotacoesService,
    private anosService: AnosService,
    private categoriasService: CategoriasService
  ) {}

  ngOnInit(): void {
    this.loadLookups();
    this.load();
  }

  loadLookups() {
    this.anosService.list().subscribe({ next: (res) => this.anos = res ?? [] });
    this.categoriasService.list().subscribe({ next: (res) => this.categorias = res ?? [] });
  }

  load() {
    this.loading = true;
    this.service.list().subscribe({
      next: (res) => { this.items = res ?? []; this.loading = false; },
      error: () => { this.loading = false; this.error = 'Falha ao carregar votações.'; }
    });
  }

  edit(item: Votacao) {
    this.editingId = item.id ?? null;
    this.form.patchValue({
      anoId: item.anoDescricao,
      categoriaId: item.categoriaId,
      nome: item.nome,
      imagemUrl: item.imagemUrl,
      dataInicio: toDatetimeLocalValue(item.dataInicio),
      dataFim: toDatetimeLocalValue(item.dataFim),
      dataPublicacao: toDatetimeLocalValue(item.dataPublicacao),
      tipo: item.tipo
    });
  }

  cancel() {
    this.editingId = null;
    this.form.reset({ anoId: '2026', categoriaId: 0, nome: '', imagemUrl: '', dataInicio: '', dataFim: '', dataPublicacao: '', tipo: 'ESCOLHA_UNICA' });
  }

  submit() {
    if (this.form.invalid) return;
    this.saving = true;
    this.error = '';

    const raw = this.form.getRawValue();
    const payload: Votacao = {
      anoId: raw.anoId,
      categoriaId: Number(raw.categoriaId),
      nome: raw.nome,
      imagemUrl: raw.imagemUrl,
      dataInicio: raw.dataInicio,
      dataFim: raw.dataFim,
      dataPublicacao: raw.dataPublicacao,
      tipo: raw.tipo
    };

    const request = this.editingId ? this.service.update(this.editingId, payload) : this.service.create(payload);
    request.subscribe({
      next: () => {
        this.saving = false;
        this.message = this.editingId ? 'Votação atualizada.' : 'Votação criada.';
        this.cancel();
        this.load();
      },
      error: () => { this.saving = false; this.error = 'Erro ao salvar votação.'; }
    });
  }

  remove(id?: number) {
    if (!id) return;
    if (!confirm('Excluir votação?')) return;
    this.service.delete(id).subscribe({ next: () => this.load(), error: () => this.error = 'Erro ao excluir votação.' });
  }

  linkPublico(id?: number): string {
    return id ? `${window.location.origin}/votacao/publico/${id}` : '';
  }

  linkAvaliador(id?: number): string {
    return id ? `${window.location.origin}/votacao/avaliador/${id}` : '';
  }

  copiarLink(link: string): void {
    if (!link) return;

    navigator.clipboard.writeText(link).then(
      () => this.message = 'Link copiado.',
      () => this.error = 'Não foi possível copiar o link.'
    );
  }
}
