import { CommonModule } from '@angular/common';
import { Component, OnInit } from '@angular/core';
import { FormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { TermosService } from '../../services/termos.service';
import { Termo } from '../../shared/models';

@Component({
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './termos.page.html'
})
export class TermosPageComponent implements OnInit {
  items: Termo[] = [];
  current: Termo | null = null;
  loading = false;
  saving = false;
  message = '';
  error = '';

  form = this.fb.nonNullable.group({
    arquivoUrl: ['', [Validators.required, Validators.minLength(5)]]
  });

  constructor(private fb: FormBuilder, private service: TermosService) {}

  ngOnInit(): void {
    this.load();
    this.loadActive();
  }

  load() {
    this.loading = true;
    this.service.list().subscribe({
      next: (res) => { this.items = res ?? []; this.loading = false; },
      error: () => { this.loading = false; this.error = 'Falha ao carregar termos.'; }
    });
  }

  loadActive() {
    this.service.ativo().subscribe({ next: (res) => this.current = res, error: () => this.current = null });
  }

  submit() {
    if (this.form.invalid) return;
    this.saving = true;
    this.service.create(this.form.getRawValue()).subscribe({
      next: () => {
        this.saving = false;
        this.message = 'Termo cadastrado.';
        this.form.reset({ arquivoUrl: '' });
        this.load();
        this.loadActive();
      },
      error: () => { this.saving = false; this.error = 'Erro ao cadastrar termo.'; }
    });
  }

  remove(id?: number) {
    if (!id) return;
    if (!confirm('Excluir termo?')) return;
    this.service.delete(id).subscribe({ next: () => { this.load(); this.loadActive(); }, error: () => this.error = 'Erro ao excluir termo.' });
  }
}
