import { Injectable } from '@angular/core';
import { ApiBaseService } from '../core/api-base.service';
import { Ano } from '../shared/models';

@Injectable({ providedIn: 'root' })
export class AnosService extends ApiBaseService {
  list() { return this.http.get<Ano[]>(`${this.baseUrl}/anos`); }
  create(payload: Ano) { return this.http.post<Ano>(`${this.baseUrl}/anos`, payload); }
}
