import { Injectable } from '@angular/core';
import { ApiBaseService } from '../core/api-base.service';
import { VotoPayload } from '../shared/models';

@Injectable({ providedIn: 'root' })
export class VotoService extends ApiBaseService {
  visualizar(id: number) { return this.http.get<any>(`${this.baseUrl}/voto/${id}/visualizacao`); }
  votar(id: number, payload: VotoPayload) { return this.http.post<any>(`${this.baseUrl}/voto/${id}/votos`, payload); }
}
