import { CommonModule } from '@angular/common';
import { Component, OnInit } from '@angular/core';
import { FormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { CandidatosService } from '../../services/candidatos.service';
import { VotacoesCandidatosService, VotacoesService } from '../../services/votacoes.service';
import { Candidato, Votacao, VotacaoCandidato } from '../../shared/models';

@Component({
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './votacoes-candidatos.page.html'
})
export class VotacoesCandidatosPageComponent implements OnInit {
  items: VotacaoCandidato[] = [];
  votacoes: Votacao[] = [];
  candidatos: Candidato[] = [];
  loading = false;
  saving = false;
  message = '';
  error = '';

  form = this.fb.nonNullable.group({
    votacaoId: [0, [Validators.required, Validators.min(1)]],
    candidatoId: [0, [Validators.required, Validators.min(1)]]
  });

  constructor(
    private fb: FormBuilder,
    private service: VotacoesCandidatosService,
    private votacoesService: VotacoesService,
    private candidatosService: CandidatosService
  ) {}

  ngOnInit(): void {
    this.loadLookups();
    this.load();
  }

  loadLookups() {
    this.votacoesService.list().subscribe({ next: (res) => this.votacoes = res ?? [] });
    this.candidatosService.list().subscribe({ next: (res) => this.candidatos = res ?? [] });
  }

  load() {
    this.loading = true;
    this.service.list().subscribe({
      next: (res) => { this.items = res ?? []; this.loading = false; },
      error: () => { this.loading = false; this.error = 'Falha ao carregar vínculos.'; }
    });
  }

  submit() {
    if (this.form.invalid) return;
    this.saving = true;
    this.service.create({ votacaoId: Number(this.form.value.votacaoId), candidatoId: Number(this.form.value.candidatoId) }).subscribe({
      next: () => {
        this.saving = false;
        this.message = 'Votação x candidato criada.';
        this.form.reset({ votacaoId: 0, candidatoId: 0 });
        this.load();
      },
      error: () => { this.saving = false; this.error = 'Erro ao salvar vínculo.'; }
    });
  }

  remove(id?: number) {
    if (!id) return;
    if (!confirm('Excluir vínculo?')) return;
    this.service.delete(id).subscribe({ next: () => this.load(), error: () => this.error = 'Erro ao excluir vínculo.' });
  }
}
