import { Routes } from '@angular/router';
import { HomeComponent } from './pages/home/home.component';
import { CategoriasPageComponent } from './pages/categorias/categorias.page';
import { AnosPageComponent } from './pages/anos/anos.page';
import { TermosPageComponent } from './pages/termos/termos.page';
import { CandidatosPageComponent } from './pages/candidatos/candidatos.page';
import { VotacoesPageComponent } from './pages/votacoes/votacoes.page';
import { VotacoesCandidatosPageComponent } from './pages/votacoes-candidatos/votacoes-candidatos.page';
import { VotoPageComponent } from './pages/voto/voto.page';
import { ApuracoesPageComponent } from './pages/apuracoes/apuracoes.page';

import { LayoutComponent } from './layout/layout.component';
import { authGuard } from './core/auth.guard';

export const routes: Routes = [
  {
    path: 'inscricao/sucesso',
    loadComponent: () =>
      import('./pages/inscricao-sucesso/inscricao-sucesso.page')
        .then(m => m.InscricaoSucessoPageComponent)
  },
  {
    path: 'inscricao/:id',
    loadComponent: () =>
      import('./pages/candidatos-public/candidatos-public.page')
        .then(m => m.CandidatosPublicPageComponent)
  },
  {
    path: 'votacao/publico/:id',
    data: { publicoAlvo: 'PUBLICO' },
    loadComponent: () =>
      import('./pages/visualizar-votacao/visualizar-votacao.component')
        .then(m => m.VisualizarVotacaoComponent)
  },
  {
    path: 'votacao/avaliador/:id',
    data: { publicoAlvo: 'AVALIADOR' },
    loadComponent: () =>
      import('./pages/visualizar-votacao/visualizar-votacao.component')
        .then(m => m.VisualizarVotacaoComponent)
  },
  {
    path: 'votacao',
    data: { publicoAlvo: 'PUBLICO' },
    loadComponent: () =>
      import('./pages/visualizar-votacao/visualizar-votacao.component')
        .then(m => m.VisualizarVotacaoComponent)
  },
  {
    path: 'votacao/:id',
    data: { publicoAlvo: 'PUBLICO' },
    loadComponent: () =>
      import('./pages/visualizar-votacao/visualizar-votacao.component')
        .then(m => m.VisualizarVotacaoComponent)
  },
  {
    path: 'login',
    loadComponent: () =>
      import('./pages/login/login.page')
        .then(m => m.LoginPageComponent)
  },
  {
    path: '',
    component: LayoutComponent,
    canActivate: [authGuard],
    children: [
      { path: '', component: HomeComponent },
      { path: 'categorias', component: CategoriasPageComponent },
      { path: 'anos', component: AnosPageComponent },
      { path: 'termos', component: TermosPageComponent },
      { path: 'candidatos', component: CandidatosPageComponent },
      { path: 'votacoes', component: VotacoesPageComponent },
      { path: 'votacoes-candidatos', component: VotacoesCandidatosPageComponent },
      { path: 'voto', component: VotoPageComponent },
      { path: 'apuracoes', component: ApuracoesPageComponent }
    ]
  },
  { path: '**', redirectTo: '' }
];
