import { Injectable } from '@angular/core';
import { ApiBaseService } from '../core/api-base.service';
import { Candidato } from '../shared/models';

@Injectable({ providedIn: 'root' })
export class CandidatosService extends ApiBaseService {
  list() { return this.http.get<Candidato[]>(`${this.baseUrl}/candidatos`); }
  get(id: number) { return this.http.get<Candidato>(`${this.baseUrl}/candidatos/${id}`); }
  create(payload: Candidato) { return this.http.post<Candidato>(`${this.baseUrl}/candidatos`, payload); }
  update(id: number, payload: Candidato) { return this.http.put<Candidato>(`${this.baseUrl}/candidatos/${id}`, payload); }
  delete(id: number) { return this.http.delete<void>(`${this.baseUrl}/candidatos/${id}`); }
}
