import { CommonModule } from '@angular/common';
import { Component, OnInit } from '@angular/core';
import { FormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { CandidatosService } from '../../services/candidatos.service';
import { Candidato } from 'src/app/shared/models';

@Component({
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './candidatos.page.html'
})
export class CandidatosPageComponent implements OnInit {

  items: any[] = [];

  categoriasProjeto = [
    { value: 'INOVACAO', label: 'Inovação' },
    { value: 'SOCIAL', label: 'Social' },
    { value: 'UNIVERSITARIO', label: 'Universitário' }
  ];

  loading = false;
  saving = false;
  editingId: number | null = null;
  message = '';
  error = '';

  form = this.fb.nonNullable.group({

    nome: ['', Validators.required],
    email: ['', [Validators.required, Validators.email]],
    telefone: ['', Validators.required],
    empresa: ['', Validators.required],

    categoriaProjeto: ['', Validators.required],

    votacaoId: [1, Validators.required],

    nomeProjeto: ['', Validators.required],

    descricao: ['', Validators.required],

    fotoUrl: [''],

    participantes: [''],

    periodoExecucao: ['', Validators.required],

    stakeholders: ['', Validators.required],

    orcamento: ['', Validators.required],

    ferramentasMetodologias: ['', Validators.required],

    resumoProjeto: ['', Validators.required],

    solucaoDesenvolvida: ['', Validators.required],

    resultadosImpacto: ['', Validators.required],

    autorizacaoAudiovisual: [false, Validators.requiredTrue],

    declaracaoVeracidade: [false, Validators.requiredTrue]

  });

  constructor(
    private fb: FormBuilder,
    private service: CandidatosService
  ) {}

  ngOnInit(): void {
    this.load();
  }

  load() {
    this.loading = true;

    this.service.list().subscribe({
      next: (res) => {
        this.items = res ?? [];
        this.loading = false;
      },
      error: () => {
        this.loading = false;
        this.error = 'Erro ao carregar candidatos.';
      }
    });
  }

  edit(item: any) {

    this.editingId = item.id ?? null;

    this.form.patchValue(item);
  }

  cancel() {

    this.editingId = null;

    this.form.reset({
      votacaoId: 1,
      autorizacaoAudiovisual: false,
      declaracaoVeracidade: false
    });
  }

  submit() {

    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    this.saving = true;
    this.error = '';

    const payload = this.form.getRawValue() as Candidato;

    const request = this.editingId
      ? this.service.update(this.editingId, payload)
      : this.service.create(payload);

    request.subscribe({

      next: () => {

        this.saving = false;

        this.message = this.editingId
          ? 'Candidato atualizado.'
          : 'Candidato criado.';

        this.cancel();

        this.load();
      },

      error: (err) => {

        this.saving = false;

        this.error =
          err?.error?.message ||
          'Erro ao salvar candidato.';
      }
    });
  }

  remove(id?: number) {

    if (!id) return;

    if (!confirm('Excluir candidato?')) return;

    this.service.delete(id).subscribe({

      next: () => this.load(),

      error: () =>
        this.error = 'Erro ao excluir candidato.'
    });
  }
}