import { HttpInterceptorFn } from '@angular/common/http';

const publicEndpoints = [
  '/auth/login',
  '/auth/votante'
];

export const authInterceptor: HttpInterceptorFn = (
  req,
  next
) => {

  const isPublic =
    publicEndpoints.some(
      endpoint => req.url.includes(endpoint)
    );

  if (isPublic || req.headers.has('Authorization')) {
    return next(req);
  }

  const adminToken =
    localStorage.getItem('auth_token');

  const votanteToken =
    localStorage.getItem('votante_token');

  const token = req.url.includes('/voto/')
    ? (votanteToken || adminToken)
    : adminToken;

  if (!token) {
    return next(req);
  }

  const cloned =
    req.clone({
      setHeaders: {
        Authorization:
          `Bearer ${token}`
      }
    });

  return next(cloned);
};
