import { Injectable } from '@angular/core';
import { ApiBaseService } from '../core/api-base.service';
import { Termo } from '../shared/models';

@Injectable({ providedIn: 'root' })
export class TermosService extends ApiBaseService {
  list() { return this.http.get<Termo[]>(`${this.baseUrl}/termos`); }
  ativo() { return this.http.get<Termo>(`${this.baseUrl}/termos/ativo`); }
  create(payload: Pick<Termo, 'arquivoUrl'>) { return this.http.post<Termo>(`${this.baseUrl}/termos`, payload); }
  delete(id: number) { return this.http.delete<void>(`${this.baseUrl}/termos/${id}`); }
}
