import { CommonModule } from '@angular/common';
import { Component, OnInit } from '@angular/core';
import { FormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { CategoriasService } from '../../services/categorias.service';
import { Categoria } from '../../shared/models';

@Component({
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './categorias.page.html'
})
export class CategoriasPageComponent implements OnInit {
  items: Categoria[] = [];
  loading = false;
  saving = false;
  editingId: number | null = null;
  message = '';
  error = '';

  form = this.fb.nonNullable.group({
    nome: ['', [Validators.required, Validators.minLength(2)]]
  });

  constructor(private fb: FormBuilder, private service: CategoriasService) {}

  ngOnInit(): void { this.load(); }

  load() {
    this.loading = true;
    this.service.list().subscribe({
      next: (res) => { this.items = res ?? []; this.loading = false; },
      error: () => { this.loading = false; this.error = 'Falha ao carregar categorias.'; }
    });
  }

  edit(item: Categoria) {
    this.editingId = item.id ?? null;
    this.form.patchValue({ nome: item.nome });
  }

  cancel() {
    this.editingId = null;
    this.form.reset({ nome: '' });
  }

  submit() {
    if (this.form.invalid) return;
    this.saving = true;
    this.error = '';
    const payload = this.form.getRawValue();
    const request = this.editingId ? this.service.update(this.editingId, payload) : this.service.create(payload);
    request.subscribe({
      next: () => {
        this.saving = false;
        this.message = this.editingId ? 'Categoria atualizada.' : 'Categoria criada.';
        this.cancel();
        this.load();
      },
      error: () => { this.saving = false; this.error = 'Erro ao salvar categoria.'; }
    });
  }

  remove(id?: number) {
    if (!id) return;
    if (!confirm('Excluir categoria?')) return;
    this.service.delete(id).subscribe({ next: () => this.load(), error: () => this.error = 'Erro ao excluir categoria.' });
  }
}
