import { CommonModule } from '@angular/common';
import { Component, OnInit } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ApuracoesService } from '../../services/apuracoes.service';
import { VotacoesService } from '../../services/votacoes.service';
import { Apuracao, Votacao } from '../../shared/models';

@Component({
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './apuracoes.page.html',
  styleUrls: ['./apuracoes.page.scss']
})
export class ApuracoesPageComponent implements OnInit {
  items: Apuracao[] = [];
  votacoes: Votacao[] = [];

  selectedVotacaoId: number | null = null;
  searchTerm = '';

  loading = false;
  loadingVotacoes = false;
  error = '';

  constructor(
    private apuracoesService: ApuracoesService,
    private votacoesService: VotacoesService
  ) {}

  ngOnInit(): void {
    this.loadVotacoes();
  }

  get filteredItems(): Apuracao[] {
    const term = this.normalize(this.searchTerm);

    if (!term) {
      return this.items;
    }

    return this.items.filter((item) => {
      const content = [
        item.candidatoNome,
        item.nomeProjeto,
        item.empresa,
        item.categoria,
        item.ano
      ]
        .filter(Boolean)
        .join(' ');

      return this.normalize(content).includes(term);
    });
  }

  get vencedor(): Apuracao | null {
    return this.items.find((item) => Number(item.posicao) === 1) ?? null;
  }

  get totalVotos(): number {
    return this.items.reduce(
      (maior, item) => Math.max(maior, Number(item.totalVotosVotacao ?? 0)),
      0
    );
  }

  get totalCandidatos(): number {
    return this.items.length;
  }

  get mediaPontuacao(): number {
    const valores = this.items
      .map((item) => item.pontuacaoApuracao)
      .filter((valor): valor is number => valor !== null && valor !== undefined);

    if (!valores.length) {
      return 0;
    }

    return valores.reduce((total, valor) => total + Number(valor), 0) / valores.length;
  }

  get votacaoSelecionada(): Votacao | undefined {
    return this.votacoes.find((votacao) => votacao.id === this.selectedVotacaoId);
  }

  loadVotacoes(): void {
    this.loadingVotacoes = true;
    this.error = '';

    this.votacoesService.list().subscribe({
      next: (response) => {
        this.votacoes = [...(response ?? [])].sort(
          (a, b) => Number(b.id ?? 0) - Number(a.id ?? 0)
        );
        this.loadingVotacoes = false;

        if (this.votacoes.length > 0) {
          this.selectedVotacaoId = this.votacoes[0].id ?? null;
        }

        this.load();
      },
      error: () => {
        this.loadingVotacoes = false;
        this.load();
      }
    });
  }

  load(): void {
    this.loading = true;
    this.error = '';

    this.apuracoesService
      .list(this.selectedVotacaoId ?? undefined)
      .subscribe({
        next: (response) => {
          this.items = [...(response ?? [])].sort((a, b) => {
            const posicaoA = Number(a.posicao ?? Number.MAX_SAFE_INTEGER);
            const posicaoB = Number(b.posicao ?? Number.MAX_SAFE_INTEGER);
            return posicaoA - posicaoB;
          });
          this.loading = false;
        },
        error: () => {
          this.items = [];
          this.loading = false;
          this.error = 'Não foi possível carregar a apuração desta votação.';
        }
      });
  }

  onVotacaoChange(votacaoId: number | null): void {
    this.selectedVotacaoId = votacaoId;
    this.searchTerm = '';
    this.load();
  }

  clearSearch(): void {
    this.searchTerm = '';
  }

  exportCsv(): void {
    const rows = this.filteredItems;

    if (!rows.length) {
      return;
    }

    const header = [
      'Posição',
      'Candidato',
      'Projeto',
      'Empresa',
      'Categoria',
      'Ano',
      'Tipo de votação',
      'Votos do candidato',
      'Total de votos',
      'Percentual',
      'Pontuação total',
      'Média ponderada',
      'Pontuação da apuração'
    ];

    const data = rows.map((item) => [
      item.posicao,
      item.candidatoNome,
      item.nomeProjeto,
      item.empresa,
      item.categoria,
      item.ano,
      item.tipoVotacao,
      item.totalVotosCandidato,
      item.totalVotosVotacao,
      item.percentual,
      item.pontuacaoTotal,
      item.mediaPonderada,
      item.pontuacaoApuracao
    ]);

    const csv = [header, ...data]
      .map((row) => row.map((value) => this.csvValue(value)).join(';'))
      .join('\r\n');

    const blob = new Blob([`\uFEFF${csv}`], {
      type: 'text/csv;charset=utf-8;'
    });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    const nomeVotacao = this.sanitizeFileName(
      this.votacaoSelecionada?.nome ?? 'todas-as-votacoes'
    );

    link.href = url;
    link.download = `apuracao-${nomeVotacao}.csv`;
    link.click();

    URL.revokeObjectURL(url);
  }

  initials(name: string | null): string {
    if (!name) {
      return '?';
    }

    return name
      .trim()
      .split(/\s+/)
      .slice(0, 2)
      .map((part) => part.charAt(0).toUpperCase())
      .join('');
  }

  hideBrokenImage(event: Event): void {
    const image = event.target as HTMLImageElement;
    image.style.display = 'none';
  }

  private normalize(value: string): string {
    return value
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .toLowerCase()
      .trim();
  }

  private csvValue(value: unknown): string {
    const text = value === null || value === undefined ? '' : String(value);
    return `"${text.replace(/"/g, '""')}"`;
  }

  private sanitizeFileName(value: string): string {
    return this.normalize(value)
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '') || 'resultado';
  }
}
